package com.ventas.service;
import com.ventas.dto.ReportModels.*;import com.ventas.dto.CatalogModels.Page;import com.ventas.repository.ReportRepository;import com.ventas.repository.AuthStore;import com.ventas.security.AuthModels.Identity;import com.ventas.security.AuthFailure;
import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;import java.nio.charset.StandardCharsets;import org.springframework.context.annotation.Profile;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;
@Service @Profile("db") public class ReportService{
 private final ReportRepository repo;private final BusinessTransactions tx;private final AuthStore auth;public ReportService(ReportRepository repo,BusinessTransactions tx,AuthStore auth){this.repo=repo;this.tx=tx;this.auth=auth;}
 private String permission(String type){return switch(type){case "ventas"->"REP.VENTAS";case "productos"->"REP.PRODUCTO";case "inventario"->"REP.INVENTARIO";case "caja"->"REP.CAJA";case "dashboard"->"REP.DASHBOARD";default->throw new AuthFailure(404,"Reporte no encontrado");};}
 private void access(Identity a,String type){if(a==null||a.cambioClaveObligatorio()||!a.permisos().contains(permission(type))||!a.rol().equals("ADM")&&!(type.equals("inventario")&&a.rol().equals("ALM")))throw new AuthFailure(403,"No tienes acceso a este reporte");}
 public Dates dates(Identity a){if(a==null||a.cambioClaveObligatorio()||a.permisos().stream().noneMatch(p->p.startsWith("REP.")))throw new AuthFailure(403,"No tienes acceso a reportes");return new Dates(repo.today());}
 Filter validate(Filter f,boolean product){if(f.desde()==null||f.hasta()==null||f.desde().isAfter(f.hasta())||f.desde().getYear()<2000||f.hasta().getYear()>9998||ChronoUnit.DAYS.between(f.desde(),f.hasta())>365||f.producto()!=null&&f.producto()<1||product&&f.producto()==null||f.buscar()==null||f.buscar().length()>100||f.pagina()<0||f.pagina()>1000000)throw new AuthFailure(400,"Selecciona un período de hasta 366 días y revisa los filtros");return f;}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public Sales sales(Identity a,String type,Filter f){if(!Set.of("ventas","productos","dashboard").contains(type))throw new AuthFailure(404,"Reporte no encontrado");access(a,type);validate(f,type.equals("productos"));return repo.sales(f);}
 public List<Map<String,Object>> products(Identity a,String q,int page){access(a,"productos");if(q==null||q.length()>100||page<0||page>1000000)throw new AuthFailure(400,"Revisa la búsqueda de productos");return repo.productOptions(q.strip(),page);}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public Tabular inventory(Identity a,Filter f){access(a,"inventario");validate(f,false);return inventory(a,f,25,false);}
 private Tabular inventory(Identity a,Filter f,int limit,boolean export){var result=repo.inventory(f,limit,export);if(a.rol().equals("ADM"))return result;var summary=new LinkedHashMap<>(result.resumen());summary.remove("valor");var rows=result.registros().items().stream().map(m->{var r=new LinkedHashMap<>(m);r.remove("costo");r.remove("valor");return (Map<String,Object>)r;}).toList();return new Tabular(result.desde(),result.hasta(),summary,new Page<>(rows,result.registros().total(),result.registros().pagina(),result.registros().tamano()));}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public Tabular cash(Identity a,Filter f){access(a,"caja");validate(f,false);return repo.cash(f,25,false);}
 @Transactional(isolation=Isolation.REPEATABLE_READ) public byte[] export(Identity a,String equipo,String type,Filter f){access(a,type);validate(f,type.equals("productos"));if(!a.permisos().contains("REP.EXPORTAR"))throw new AuthFailure(403,"No tienes permiso para descargar reportes");return tx.write(a,equipo,"REP.EXPORTAR",()->{var user=auth.lockUser(a.id()).orElseThrow(AuthFailure::expired);if(!user.rol().equals(a.rol())||!auth.permissions(a.id()).contains(permission(type)))throw new AuthFailure(403,"Los permisos del reporte cambiaron");List<Map<String,Object>> rows;List<String> columns;
 if(type.equals("ventas")||type.equals("productos")){rows=repo.sales(f).dias();columns=List.of("fecha","neto","costo","margen");}
 else if(type.equals("inventario")){var r=inventory(a,f,5001,true);if(r.registros().total()>5000)throw new AuthFailure(400,"La descarga admite hasta 5000 productos. Ajusta la búsqueda");rows=r.registros().items();columns=a.rol().equals("ADM")?List.of("codigo","producto","unidad","stock","minimo","costo","valor","entradas","salidas"):List.of("codigo","producto","unidad","stock","minimo","entradas","salidas");}
 else if(type.equals("caja")){rows=repo.cash(f,5001,true).registros().items();columns=List.of("id","fecha","estado","inicial","ingresos","egresos","efectivo","yape","debito","diferencia");}
 else throw new AuthFailure(400,"Descarga disponible desde un reporte");String csv=csv(columns,rows);repo.audit(a.id(),type,f);return csv.getBytes(StandardCharsets.UTF_8);});}
 String csv(List<String> columns,List<Map<String,Object>> rows){var out=new StringBuilder("\uFEFF");out.append(String.join(";",columns)).append("\r\n");for(var row:rows){var cells=new ArrayList<String>();for(String col:columns){String value=Objects.toString(row.get(col),"");if(!value.matches("-?[0-9]+([.][0-9]+)?")&&(value.stripLeading().matches("(?s)[=+@-].*")||value.startsWith("\t")||value.startsWith("\r")))value="'"+value;cells.add("\""+value.replace("\"","\"\"")+"\"");}out.append(String.join(";",cells)).append("\r\n");}return out.toString();}
}
